pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool sent, ) = address(c).call{value: 10 ether}("");
        require(sent);
        vm.prank(alice);
        c.withdraw();
        assertTrue(c.balances(alice) == 0);
    }
}
